      "check_id": "CKV_AZURE_94",
      "title": "Ensure that MySQL server enables geo-redundant backups",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Geo-redundant backups ensure data availability in case of a regional outage. The current configuration does not enable this feature."
    },
    {
      "check_id": "CKV_AZURE_53",
      "title": "Ensure 'public network access enabled' is set to 'False' for MySQL servers",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Allowing public network access increases the attack surface of the database. It should be disabled to restrict access to private networks."
    },
    {
      "check_id": "CKV_AZURE_54",
      "title": "Ensure MySQL is using the latest version of TLS encryption",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Using the latest version of TLS ensures secure communication. The current configuration does not specify the minimum TLS version."
    },
    {
      "check_id": "CKV2_AZURE_44",
      "title": "Ensure Azure MySQL server is configured with private endpoint",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Private endpoints provide secure connectivity to the database over a private network. The current configuration does not include a private endpoint."
